#include <bits/stdc++.h>

using namespace std;

const int MODULUS = 1000000007;
int prime, power, result, visited_flags[1048576];

int calculate() {
    result = 1;
    if (power == 0) {
        for (int i = 1; i < prime; ++i) {
            result = (long long)result * prime % MODULUS;
        }
    } else if (power == 1) {
        for (int i = 1; i <= prime; ++i) {
            result = (long long)result * prime % MODULUS;
        }
    } else {
        for (int i = 0; i < prime; ++i) {
            if (!visited_flags[i]) {
                int cycle_length = 0;
                int index = i;
                while (!visited_flags[index]) {
                    visited_flags[index] = 1;
                    ++cycle_length;
                    index = (long long)index * power % prime;
                }
                if (index != 0) {
                    result = (long long)result * prime % MODULUS;
                }
            }
        }
    }
    return result;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("data", "r", stdin);
#endif
    cin >> prime >> power;
    cout << calculate();
}
